function randomQuickSort(arr, lo=0, hi=arr.length-1){
  if(lo>=hi)return arr;
  const pivotIdx=lo+Math.floor(Math.random()*(hi-lo+1));
  [arr[pivotIdx],arr[hi]]=[arr[hi],arr[pivotIdx]];
  const pivot=arr[hi];let p=lo;
  for(let i=lo;i<hi;i++){if(arr[i]<=pivot){[arr[p],arr[i]]=[arr[i],arr[p]];p++;}}
  [arr[p],arr[hi]]=[arr[hi],arr[p]];
  randomQuickSort(arr,lo,p-1);randomQuickSort(arr,p+1,hi);
  return arr;
}
function quickSort3Way(arr, lo=0, hi=arr.length-1){
  if(lo>=hi)return arr;
  const pivotIdx=lo+Math.floor(Math.random()*(hi-lo+1));
  const pivot=arr[pivotIdx];
  let lt=lo,gt=hi,i=lo;
  while(i<=gt){if(arr[i]<pivot){[arr[lt],arr[i]]=[arr[i],arr[lt]];lt++;i++;}else if(arr[i]>pivot){[arr[i],arr[gt]]=[arr[gt],arr[i]];gt--;}else i++;}
  quickSort3Way(arr,lo,lt-1);quickSort3Way(arr,gt+1,hi);
  return arr;
}
const randomQuickSortImpl=randomQuickSort;
const quickSort3WayImpl=quickSort3Way;

