const MAX_LEVEL=16;
class SkipNode{constructor(key,val,level){this.key=key;this.val=val;this.forward=new Array(level+1).fill(null);}}
class SkipList{
  constructor(){this.header=new SkipNode(-Infinity,null,MAX_LEVEL);this.level=0;}
  _randomLevel(){let lvl=0;while(Math.random()<0.5&&lvl<MAX_LEVEL)lvl++;return lvl;}
  search(key){let curr=this.header;for(let i=this.level;i>=0;i--){while(curr.forward[i]&&curr.forward[i].key<key){curr=curr.forward[i];}}curr=curr.forward[0];return(curr&&curr.key===key)?curr.val:undefined;}
  insert(key,val){const update=new Array(MAX_LEVEL+1).fill(this.header);let curr=this.header;for(let i=this.level;i>=0;i--){while(curr.forward[i]&&curr.forward[i].key<key){curr=curr.forward[i];}update[i]=curr;}curr=curr.forward[0];if(curr&&curr.key===key){curr.val=val;return;}const newLevel=this._randomLevel();if(newLevel>this.level){for(let i=this.level+1;i<=newLevel;i++)update[i]=this.header;this.level=newLevel;}const newNode=new SkipNode(key,val,newLevel);for(let i=0;i<=newLevel;i++){newNode.forward[i]=update[i].forward[i];update[i].forward[i]=newNode;}}
}

