function estimatePi(n){
  let inside=0;
  for(let i=0;i<n;i++){const x=Math.random(),y=Math.random();if(x*x+y*y<=1)inside++;}
  return 4*inside/n;
}
function millerRabin(n,k=10){
  if(n<2)return false;if(n===2||n===3)return true;if(n%2===0)return false;
  let r=0,d=n-1;while(d%2===0){d>>=1;r++;}
  function modPow(base,exp,mod){let result=1n;base=BigInt(base)%BigInt(mod);exp=BigInt(exp);const m=BigInt(mod);while(exp>0n){if(exp&1n)result=result*base%m;base=base*base%m;exp>>=1n;}return Number(result);}
  for(let i=0;i<k;i++){const a=2+Math.floor(Math.random()*(n-4));let x=modPow(a,d,n);if(x===1||x===n-1)continue;let composite=true;for(let j=0;j<r-1;j++){x=modPow(x,2,n);if(x===n-1){composite=false;break;}}if(composite)return false;}
  return true;
}
const estimatePiImpl=estimatePi;
const millerRabinImpl=millerRabin;

