class WeightedRandom{
  constructor(w){this.prefix=[0];for(const x of w)this.prefix.push(this.prefix.at(-1)+x);this.total=this.prefix.at(-1);}
  pickIndex(){const r=Math.random()*this.total;let lo=1,hi=this.prefix.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(this.prefix[mid]<=r)lo=mid+1;else hi=mid;}return lo-1;}
}
function classifyAlgorithm(name){
  const lasVegas=['quicksort','quickselect','skip list','reservoir sampling'];
  const monteCarlo=['miller-rabin','bloom filter','hyperloglog','monte carlo integration'];
  const n=name.toLowerCase();
  if(lasVegas.some(x=>n.includes(x)))return'Las Vegas';
  if(monteCarlo.some(x=>n.includes(x)))return'Monte Carlo';
  return'Deterministic';
}
